// Editable design study. All pitches and document contents are synthetic fixtures.
// No audio, MIDI connection, real clipboard, file reads, or persistence.
(()=>{
const params=new URLSearchParams(location.search),scene=Number(params.get('scene')||1);
const modeNaming=params.get('kind')==='mode';
const operation=params.get('operation')||'save';
const titles=['Collect chord','Name & slot','Collect mode','Edit & arrange','Save document','Unsaved changes'];
const ids=['07-collect-chord','08-name-chord','09-collect-mode','10-edit-slots','11-save-document','12-unsaved-changes'];
const chromatic=Array.from({length:12},(_,i)=>i),ref=60;
let picked=scene===3||modeNaming?[60,62,64,67,69,72]:[64,67,71,72];
let draftName=modeNaming?'Open pent':'Open maj7';
let slot=6,clipboard='Mm triad',kind=scene===3||modeNaming?'mode':'chord';
const rootEl=document.getElementById('instrument');
const go=(next,extra='')=>{location.href=`?scene=${next}${extra}`;};
const button=(text,cls='',action='')=>`<button class="action ${cls}" ${action?`data-action="${action}"`:''}>${text}</button>`;
const headerView=()=>`<header class="app-header"><div class="brand">▦ harmony grid <small>Ⅰ</small></div><nav class="app-menu" aria-label="Instrument menus"><button data-go="5" ${scene>=5?'class="current"':''}>File</button><button data-go="4" ${scene===4?'class="current"':''}>Edit</button><button data-go="1" ${scene<=3?'class="current"':''}>Make</button><button data-action="help">Help</button></nav><div class="header-right"><span class="document-title"><span class="dirty-dot"></span><strong>Open Voicings</strong><span> · Unsaved</span></span><span class="sound-select">Organ &nbsp;⌄</span></div></header>`;
function captureView(isMode=false){
 const draft={base:36,axes:[4,3],root:0,scale:chromatic,played:picked,filtered:[],held:[],midi:[],anchor:ref};
 const pc=[...new Set(picked.map(p=>(p-ref+120)%12))].sort((a,b)=>a-b);
 return `${headerView()}<div class="capture-layout ${isMode?'mode-capture':''}"><section class="capture-stage"><div class="step-heading"><div><div class="eyebrow">Make ${isMode?'mode':'chord'} <kbd>${isMode?'M':'N'}</kbd></div><h1>Choose your pitches</h1><p>Click notes on the grid or clavier. Select a note again to remove it.</p></div><div class="steps"><b>1</b> Collect <i></i><span>2</span> Name & slot</div></div><div class="capture-tools"><strong>Raw pitches · Solo / Chromatic</strong><span>→ 4 ↑ 3 &nbsp; · &nbsp; Auto Button off</span></div><div class="capture-grid">${grid(draft,{cols:14,rows:6,base:36,id:'capture'})}</div><div class="capture-tools"><strong>Clavier <span class="muted">C3–C6</span></strong><span>Mouse + MIDI selection</span></div><div class="capture-clavier">${keyboard(draft)}</div><div class="capture-legend"><span><i></i>Selected pitch</span><span><i class="reference"></i>Reference pitch class</span><span>No chord expansion or scale filtering</span></div></section><aside class="capture-panel"><div class="panel-title"><h3>Your ${isMode?'mode':'chord'}</h3><span class="count">${picked.length} pitches</span></div><div class="reference-card"><span class="mini-label">${isMode?'Mode root':'Chord anchor'} · fixed reference</span><strong>C4</strong><p class="small">${picked.includes(ref)?'The first selected pitch sets the reference.':'Removed from selection.<br>Still the anchor for these intervals.'}</p></div><div class="note-list">${picked.map(p=>`<div class="note-row"><strong>${note(p)}</strong><span>${p-ref===0?'Reference':`+${p-ref} semitones`}</span><button data-remove="${p}" aria-label="Remove ${note(p)}">×</button></div>`).join('')||'<p class="small muted">No pitches selected. The reference remains C4.</p>'}</div>${isMode?`<div class="mode-result"><span class="mini-label">${pc.length} distinct mode tones</span><div class="pitch-classes">${chromatic.map(p=>`<span class="${pc.includes(p)?'selected':''}">${NAMES[p]}</span>`).join('')}</div><p class="small muted">C4 and C5 are separate selections.<br>Both become C in the finished mode.</p></div>`:`<p class="small muted">Octave spacing is preserved.<br>C5 stays +12 above the anchor.</p>`}<div class="panel-foot"><p class="small muted">Holding ${isMode?'M':'N'}? Release it to name the ${isMode?'mode':'chord'}.</p><button class="action primary" data-go="2" ${isMode?'data-extra="&kind=mode"':''} ${picked.length?'':'disabled'}>Name & choose slot →</button><button class="cancel" data-action="cancel">Cancel collection</button></div></aside></div>`;
}
function naming(){
 const isMode=modeNaming,notes=isMode?[60,62,64,67,69,72]:[64,67,71,72];
 const names=isMode?['Chromatic','Major','Nat. minor','Harm. minor','Mel. minor','Pentatonic','Whole tone','Dorian','Mixolydian','Blues']:['Solo','Mm triad','Major','Minor','Dominant 7','Major 7','Minor 7','Mm7','Extended','Octaves'];
 return `<div class="shade"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-head"><div class="eyebrow">Make ${isMode?'mode':'chord'} · 2 of 2</div><h1 id="dialog-title">Name & choose a slot</h1><p class="small muted">Choose a slot with 2–0, then press Tab to enter a name.</p></header><div class="dialog-body"><div class="field"><label for="pattern-name">${isMode?'Mode':'Chord'} name</label><input id="pattern-name" value="${isMode?'Open pent':'Open maj7'}"><p class="small muted">Short names are easier to read while playing.</p></div><div class="field"><label>Keyboard slot</label><div class="slot-picker">${names.map((name,i)=>`<button data-slot="${(i+1)%10}" class="${(i+1)%10===slot?'selected':''}" ${i===0?'disabled':''} title="${(i+1)%10} · ${name}${i===0?' · protected':''}">${(i+1)%10}</button>`).join('')}</div><p class="small muted">1 · ${isMode?'Chromatic':'Solo'} is protected.</p><div class="replacement">Replaces <strong>slot ${slot} · ${names[slot===0?9:slot-1]}</strong> in this instrument.</div></div><div class="summary-row"><span>${isMode?'Root':'Anchor'}</span><strong>C4${isMode?'':' · not selected'}</strong></div><div class="selected-notes">${notes.map(p=>`<span>${note(p)}</span>`).join('')}</div><p class="small muted">${isMode?'6 selected pitches → 5 mode tones: C · D · E · G · A.':'Intervals from the anchor: +4 · +7 · +11 · +12 semitones.'}</p></div><footer class="dialog-foot actions"><button class="action left" data-go="${isMode?3:1}">← Edit pitches</button>${button('Cancel','','cancel')}${button(`Replace ${isMode?'mode':'chord'}`,'primary','replace')}</footer></section></div>`;
}
function arrangeView(){
 const isMode=params.get('target')==='mode';
 const names=isMode?['Chromatic','Major','Natural minor','Harmonic minor','Melodic minor','Open pent','Whole tone','Dorian','Mixolydian','Blues']:['Solo','Mm triad','Major','Minor','Dominant 7','Open maj7','Minor 7','Mm7','Extended','Octaves'];
 const offsets=isMode?['12 tones','7 tones','7 tones','7 tones','7 tones','5 tones','6 tones','7 tones','7 tones','6 tones']:['0','0 · 3 · 4 · 7','0 · 4 · 7','0 · 3 · 7','0 · 4 · 7 · 10','4 · 7 · 11 · 12','0 · 3 · 7 · 10','0 · 3 · 4 · 7 · 10','0 · 4 · 7 · 10 · …','0 · 12 · 24'];
 return `${headerView()}<section class="arrange"><div class="arrange-header"><div><div class="eyebrow">Edit instrument</div><h1>Arrange your playing vocabulary</h1><p>Keep the patterns you alternate between on neighboring keys.</p></div><div class="actions">${button('Make chord · N','','make-chord')}${button('Make mode · M','','make-mode')}</div></div><div class="arrange-body"><div class="slots-pane"><nav class="tabs"><button class="${isMode?'':'active'}" data-go="4">Chords</button><button class="${isMode?'active':''}" data-go="4" data-extra="&target=mode">Modes</button></nav><div class="slot-table">${names.map((name,i)=>`<button class="slot-card ${i===5?'active':''}" data-action="slot-preview"><span class="digit">${(i+1)%10}</span><span><strong>${name}</strong><small>${offsets[i]}</small></span>${i===0?'<span class="lock">Protected</span>':''}</button>`).join('')}</div><p class="slot-note">Copy and paste stay within ${isMode?'modes':'chords'}. Slot 1 cannot be replaced.</p></div><aside class="detail"><span class="eyebrow">${isMode?'Mode':'Chord'} · slot 6</span><h2>${isMode?'Open pent':'Open maj7'}</h2><div class="field"><label for="edit-name">Name</label><input id="edit-name" value="${isMode?'Open pent':'Open maj7'}"></div><span class="mini-label">${isMode?'Pitch classes from root':'Semitones from lead pitch'}</span><div class="intervals">${(isMode?[0,2,4,7,9]:[4,7,11,12]).map(n=>`<span>${n===0?'0':'+'+n}</span>`).join('')}</div><p class="small reference-note">${isMode?'Octave-equivalent pitches form one mode tone.':'The lead is the reference, even though this chord has no note at offset 0.'}</p><button class="action secondary" data-go="${isMode?3:1}">Edit pitches…</button><div class="clipboard"><span>Copied ${isMode?'mode':'chord'}<br><strong>${isMode?'Major':clipboard}</strong></span><button class="action" data-action="copy">Copy</button></div><p class="small" style="margin-top:10px">Paste replaces slot 6 with the copied ${isMode?'mode':'chord'}.</p><div class="actions">${button('Paste here','','paste')}${button('Apply changes','primary','apply')}</div></aside></div></section>`;
}
function documentView(){const isOpen=operation==='open';return `<div class="shade"><section class="dialog wide" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-head"><div class="eyebrow">Instrument document</div><h1 id="dialog-title">Keep this instrument</h1><p class="small muted">Your chords, modes, sound, and playing settings travel together.</p></header><div class="dialog-body document-layout"><div><nav class="file-options">${[['New instrument',''],['Open…','⌘O'],['Save','⌘S'],['Save As…','⇧⌘S'],['Revert to saved…','']].map(([n,k])=>`<button class="${n===(isOpen?'Open…':'Save As…')?'selected':''}" data-action="${n==='Save As…'?'save-as':n==='Open…'?'open-file':n==='Revert to saved…'?'revert-file':'file-action'}">${n}${k?`<kbd>${k}</kbd>`:''}</button>`).join('')}</nav><div class="note-banner small">Live Sustain, Hold, Drone, and Repeat states start inactive when another instrument opens.</div></div><div class="file-info">${isOpen?`<h2>Open an instrument</h2><p class="small">Choose an instrument file from your computer.</p><div class="file-tile"><div class="file-icon">▦</div><strong>Chords, modes, and playing settings</strong><p>The selected file is checked before it replaces your current instrument.</p><div class="small">If you have unsaved changes, you can save them, discard them, or cancel opening.</div></div><div class="note-banner">Your current notes continue until the new instrument opens.</div>`:`<h2>Save As…</h2><div class="field"><label for="file-name">Instrument name</label><input id="file-name" value="Open Voicings"><p class="small">Save a separate instrument file. Choose its location in the next step.</p></div><div class="document-preview"><div class="summary-row"><span>Chords / modes</span><strong>10 / 10 slots</strong></div><div class="summary-row"><span>Grid axes</span><strong>→ 4 &nbsp; ↑ 3</strong></div><div class="summary-row"><span>Scale</span><strong>C Major</strong></div><div class="summary-row"><span>Sound</span><strong>Organ</strong></div><div class="summary-row"><span>Tempo</span><strong>240 ticks / min</strong></div></div><p class="small">Opening another instrument releases the current notes immediately.</p>`}</div></div><footer class="dialog-foot actions">${button('Cancel','','cancel')}${button(isOpen?'Choose instrument file…':'Choose location & save…','primary',isOpen?'choose-open':'save')}</footer></section></div>`;}
function changeItems(){
 const items=['Chord 6 changed to Open maj7','Mode 6 changed to Open pent','Tempo changed to 240 ticks / min'];
 if(params.get('changes')==='many')items.push('Grid horizontal interval changed to 4 semitones','Grid vertical interval changed to 3 semitones','Sound changed to Organ','Scale root changed to C','Selected mode changed to Major','Auto Button turned off','Smooth Clavier turned on','Hold Number changed to 12','Clavier low octave changed to 3','Grid low octave changed to 2','MIDI Play Chords turned on','MIDI Thru turned off','Chord 9 renamed to Extended voicing with a doubled octave and a suspended upper note');
 if(params.get('changes')==='many')items.push(...Array.from({length:24},(_,i)=>`Additional test change ${i+1}: ${i%2===0?'chord voicing adjusted':'mode selection updated'}${i===23?' — final entry in the 40-change scroll test':''}`));
 return items.map(text=>`<li>${text}</li>`).join('');
}
function unsavedView(){if(operation==='revert')return `<div class="shade"><section class="dialog unsaved" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-head"><span class="warning-icon">!</span><div class="eyebrow">Revert to saved</div><h1 id="dialog-title">Restore the saved instrument?</h1><p class="muted">Changes to Open Voicings since the last save will be discarded.</p></header><div class="dialog-body"><p class="small muted">The saved chords, modes, and playing settings replace the current version. Current notes release when the saved version loads.</p></div><footer class="dialog-foot actions">${button('Cancel','left','cancel')}${button('Revert to saved','danger-soft','confirm-revert')}</footer></section></div>`;return `<div class="shade"><section class="dialog unsaved" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-head"><span class="warning-icon">!</span><div class="eyebrow">Open another instrument</div><h1 id="dialog-title">Save changes to Open Voicings?</h1><p class="muted">You have changes that have not been saved to its file.</p></header><div class="dialog-body"><ul class="changes" tabindex="0" aria-label="Unsaved changes">${changeItems()}</ul><p class="small muted">The current instrument stays open until you choose. Your notes are released when the next instrument opens.</p></div><footer class="dialog-foot actions">${button('Cancel','left','cancel')}${button('Discard & open','danger-soft','discard')}${button('Save & open…','primary','save-open')}</footer></section></div>`;}
function toast(text){document.getElementById('feedback').textContent=text;}
function render(){
 if(scene===1||scene===3)rootEl.innerHTML=captureView(scene===3);
 else if(scene===2){rootEl.innerHTML=captureView(modeNaming)+naming();}
 else if(scene===4)rootEl.innerHTML=arrangeView();
 else{rootEl.innerHTML=surface(S['1']);rootEl.querySelector('.app-header').outerHTML=headerView();rootEl.insertAdjacentHTML('beforeend',scene===5?documentView():unsavedView());}
 document.getElementById('review-bar').innerHTML=`<span class="review-label">DESIGN 02 · NO AUDIO</span><nav class="review-nav" aria-label="Authoring review states">${titles.map((title,i)=>`<a href="?scene=${i+1}" class="${i+1===scene?'active':''}" ${i+1===scene?'aria-current="page"':''}>${i+1} ${title}</a>`).join('')}</nav><span class="review-caption">Illustrated fixtures · Each screen resets on entry</span>`;
 if(!document.getElementById('feedback'))document.body.insertAdjacentHTML('beforeend','<div id="feedback" role="status"></div>');
 rootEl.querySelectorAll('[data-go]').forEach(el=>el.onclick=()=>go(el.dataset.go,el.dataset.extra||''));
 rootEl.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{picked=picked.filter(p=>p!==+el.dataset.remove);render();});
 if(scene===1||scene===3)rootEl.querySelectorAll('[data-pitch],[data-key]').forEach(el=>el.onclick=()=>{const p=Number(el.dataset.pitch??el.dataset.key);picked=picked.includes(p)?picked.filter(n=>n!==p):[...picked,p].sort((a,b)=>a-b);render();});
 const nameInput=rootEl.querySelector('#pattern-name');
 if(nameInput){nameInput.value=draftName;nameInput.oninput=()=>{draftName=nameInput.value;};}
 rootEl.querySelectorAll('[data-slot]').forEach(el=>el.onclick=()=>{slot=+el.dataset.slot;render();});
 rootEl.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{
  const a=el.dataset.action;
  if(a==='make-chord')return go(1);if(a==='make-mode')return go(3);
  if(a==='replace'||a==='apply')return go(4,modeNaming?'&target=mode':'');
  if(a==='save-open'||a==='save-as')return go(5);
  if(a==='open-file')return go(5,'&operation=open');
  if(a==='choose-open')return go(6);
  if(a==='revert-file')return go(6,'&operation=revert');
  const messages={'confirm-revert':'Preview: restore the last saved instrument and release the previous notes.',cancel:'Preview: return to the unchanged instrument.',copy:'Preview: selected pattern copied within this instrument.',paste:'Preview: copied pattern replaces slot 6; document becomes unsaved.',save:'Preview: the system file chooser opens next. No file is written here.',discard:'Preview: open the selected instrument and release the previous notes.',help:'Hold N for chord collection or M for mode collection. Release to name and choose a slot.','slot-preview':'Preview: select this slot to inspect, rename, copy, or edit its pitches.','file-action':'Preview: this follows the standard file workflow. Unsaved changes are checked first.'};toast(messages[a]||'Design preview only.');
 });
 document.title=`Harmony Grid — ${ids[scene-1]} — design prototype`;
 window.authoringFixture={state:String(scene),operation,kind,selectedPitches:picked,reference:ref,slot,modeTones:scene===3?[0,2,4,7,9]:null};
}
render();
if(params.has('qa'))setTimeout(()=>{
 const area=rootEl.getBoundingClientRect(),scope=rootEl.querySelector('.dialog')||rootEl;
 const checked=[...scope.querySelectorAll('button,input,h1,h2,h3,p,.summary-row,.note-row,.capture-legend')];
 const outside=checked.filter(el=>{const r=el.getBoundingClientRect();return r.width&&r.height&&(r.left<area.left-1||r.right>area.right+1||r.top<area.top-1||r.bottom>area.bottom+1)}).map(el=>el.textContent||el.id);
 const overflow=checked.filter(el=>el.clientWidth&&el.scrollWidth>el.clientWidth+2).map(el=>el.textContent||el.id);
 const list=scope.querySelector('.changes');
 let changesList=null;
 if(list){
  const footer=scope.querySelector('.dialog-foot'),before=footer.getBoundingClientRect().top;
  list.scrollTop=list.scrollHeight;
  const last=list.lastElementChild.getBoundingClientRect(),bounds=list.getBoundingClientRect();
  changesList={count:list.children.length,clientHeight:list.clientHeight,scrollHeight:list.scrollHeight,scrollTop:list.scrollTop,lastItemVisible:last.top>=bounds.top&&last.bottom<=bounds.bottom,footerStationary:before===footer.getBoundingClientRect().top,paddingLeft:parseFloat(getComputedStyle(list).paddingLeft)};
  list.scrollTop=0;
 }
 const out=document.createElement('script');out.type='application/json';out.id='authoring-qa';out.textContent=JSON.stringify({...window.authoringFixture,viewport:{width:innerWidth,height:innerHeight},outside,controlOverflow:overflow,changesList,documentHeight:document.documentElement.scrollHeight});document.body.append(out);
},150);
})();
